// Some portions generated by Codex
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawn, spawnSync } = require('node:child_process');
const test = require('node:test');

function run(shardExit = 0, mergeExit = 0, display = false, testCount = 6, filters = []) {
    const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-playwright-runner-'));
    const trace = path.join(temporary, 'commands.jsonl');
    fs.writeFileSync(path.join(temporary, 'npx'), `#!${process.execPath}
const fs = require('node:fs');
const args = process.argv.slice(2);
const log = event => fs.appendFileSync(process.env.RUNNER_TRACE, JSON.stringify(event) + '\\n');
if (args[1] === 'merge-reports') {
    log({type:'merge', args});
    fs.writeFileSync(process.env.PLAYWRIGHT_JSON_OUTPUT_FILE, JSON.stringify({stats:{
        expected:Number(process.env.RUNNER_TEST_COUNT), unexpected:0, flaky:0, skipped:0
    }}));
    process.exit(Number(process.env.MERGE_EXIT));
}
const shard = args.find(arg => arg.startsWith('--shard='));
log({type:'start', args, blob:process.env.PLAYWRIGHT_BLOB_OUTPUT_FILE, display:process.env.DISPLAY});
const deadline = Date.now() + 10000;
const timer = setInterval(() => {
    const starts = fs.readFileSync(process.env.RUNNER_TRACE, 'utf8').trim().split('\\n')
        .map(JSON.parse).filter(event => event.type === 'start');
    const expected = Number(process.env.RUNNER_EXPECTED_STARTS);
    if (starts.length < expected && Date.now() < deadline) return;
    clearInterval(timer);
    log({type:'finish', shard});
    process.exit(starts.length < expected ? 97 : shard === '--shard=1/2' ? Number(process.env.SHARD_EXIT) : 0);
}, 10);
`, { mode: 0o755 });
    fs.writeFileSync(path.join(temporary, 'xvfb-run'), `#!/bin/bash
while [ "$#" -gt 0 ]; do
  case "$1" in -a) shift;; -s) shift 2;; *) break;; esac
done
export DISPLAY=":$BASHPID"
exec "$@"
`, { mode: 0o755 });
    const outcome = spawnSync(process.execPath, [path.resolve(__dirname, '../run-playwright.js'),
        'selected.spec.js', ...filters], {
        cwd: temporary,
        env: { ...process.env, PATH: `${temporary}${path.delimiter}${process.env.PATH}`,
            RUNNER_TRACE: trace, SHARD_EXIT: String(shardExit), MERGE_EXIT: String(mergeExit),
            RUNNER_TEST_COUNT: String(testCount),
            RUNNER_EXPECTED_STARTS: String(filters.length ? 1 : 2),
            E2E_SHARDS: '2', E2E_BROWSER: 'webkit', E2E_NEEDS_XVFB: String(display) },
        encoding: 'utf8', timeout: 20000
    });
    const events = fs.existsSync(trace) ? fs.readFileSync(trace, 'utf8').trim().split('\n').map(JSON.parse) : [];
    return { outcome, events };
}

test('two shards overlap, isolate output and displays, and merge after both finish', () => {
    const { outcome, events } = run(0, 0, true);
    assert.equal(outcome.status, 0, outcome.stdout + outcome.stderr);
    assert.deepEqual(events.map(event => event.type), ['start', 'start', 'finish', 'finish', 'start', 'finish', 'merge']);
    const starts = events.filter(event => event.type === 'start').slice(0, 2);
    assert.equal(new Set(starts.map(event => event.display)).size, 2);
    assert.equal(new Set(starts.map(event => event.blob)).size, 2);
    assert.deepEqual(starts.map(event => event.args.find(arg => arg.startsWith('--shard='))).sort(),
        ['--shard=1/2', '--shard=2/2']);
    for (const { args } of starts) {
        assert.ok(args.includes('--workers=1'));
        assert.ok(args.includes('--project=webkit'));
        assert.ok(args.includes('selected.spec.js'));
        assert.ok(args.includes('--reporter=line,blob'));
        assert.ok(args.some(arg => arg.startsWith('--grep-invert=')));
    }
    assert.equal(new Set(starts.map(event => event.args.find(arg => arg.startsWith('--output=')))).size, 2);
    const isolated = events[4];
    const selection = isolated.args.find(arg => arg.startsWith('--grep=')).slice('--grep='.length);
    assert.ok(starts.every(event => event.args.includes(`--grep-invert=${selection}`)));
    const matches = new RegExp(selection);
    for (const file of ['workbench-round3-server', 'workbench-destructive-actions',
        'workbench-live-route-parity', 'workbench-visual-refinement-operation-states']) {
        assert.ok(matches.test(`webkit tests/${file}.spec.js safety check`), file);
    }
    assert.ok(matches.test('webkit graph timing @performance'));
    assert.equal(matches.test('webkit tests/workbench-spacing-audit.spec.js picker pagination'), false);
    assert.ok(isolated.args.includes('--workers=1'));
    assert.ok(isolated.args.includes('--output=test-results/isolated'));
    assert.ok(starts.every(event => event.blob !== isolated.blob));
    assert.ok(events.at(-1).args.includes('--reporter=html,json'));
});

test('a failed shard still waits for its peer and merges diagnostics, then fails the run', () => {
    const { outcome, events } = run(7);
    assert.equal(outcome.status, 7, outcome.stdout + outcome.stderr);
    assert.equal(events.filter(event => event.type === 'finish').length, 3);
    assert.equal(events.at(-1).type, 'merge');
});

test('a report merge failure cannot turn a successful test run green', () => {
    const { outcome } = run(0, 8);
    assert.equal(outcome.status, 8, outcome.stdout + outcome.stderr);
});

test('an empty overall selection fails even though individual phases may be empty', () => {
    const { outcome } = run(0, 0, false, 0);
    assert.equal(outcome.status, 1, outcome.stdout + outcome.stderr);
    assert.match(outcome.stderr, /No tests found in the selected E2E suite/);
});

for (const filters of [['--grep=selected'], ['-g', 'selected'], ['--grep-invert=excluded'], ['-G', 'excluded']]) {
    test(`focused ${filters.join(' ')} is forwarded without replacement`, () => {
        const { outcome, events } = run(0, 0, false, 6, filters);
        assert.equal(outcome.status, 0, outcome.stdout + outcome.stderr);
        assert.deepEqual(events.map(event => event.type), ['start', 'finish']);
        assert.deepEqual(events[0].args.slice(-filters.length), filters);
        assert.ok(events[0].args.every(arg => !arg.startsWith('--shard=')));
    });
}

for (const [signal, status] of [['SIGINT', 130], ['SIGTERM', 143]]) {
    test(`${signal} reaches browser descendants and retains the interrupted exit status`, { timeout: 15000 }, async () => {
        const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-playwright-signal-'));
        const trace = path.join(temporary, 'signals.jsonl');
        const descendant = path.join(temporary, 'browser.js');
        fs.writeFileSync(descendant, `
const fs = require('node:fs');
const log = event => fs.appendFileSync(process.env.RUNNER_TRACE, JSON.stringify(event) + '\\n');
for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => {
    log({type:'signal', process:'browser', signal}); process.exit(0);
});
log({type:'ready', process:'browser'});
setInterval(() => {}, 1000);
`);
        fs.writeFileSync(path.join(temporary, 'npx'), `#!${process.execPath}
const fs = require('node:fs');
const {spawn} = require('node:child_process');
const log = event => fs.appendFileSync(process.env.RUNNER_TRACE, JSON.stringify(event) + '\\n');
if (process.argv.includes('merge-reports')) { log({type:'merge'}); process.exit(0); }
for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => {
    log({type:'signal', process:'playwright', signal});
});
log({type:'ready', process:'playwright'});
const child = spawn(process.execPath, [process.env.RUNNER_DESCENDANT], {stdio:'inherit'});
child.once('exit', () => process.exit(0));
`, { mode: 0o755 });
        const child = spawn(process.execPath, [path.resolve(__dirname, '../run-playwright.js')], {
            cwd: temporary,
            env: { ...process.env, PATH: `${temporary}${path.delimiter}${process.env.PATH}`,
                RUNNER_TRACE: trace, RUNNER_DESCENDANT: descendant, E2E_SHARDS: '1', E2E_NEEDS_XVFB: 'false' },
            stdio: ['ignore', 'pipe', 'pipe']
        });
        let output = '';
        child.stdout.on('data', chunk => { output += chunk; });
        child.stderr.on('data', chunk => { output += chunk; });
        const completion = new Promise(resolve => child.once('close', (code, signal) => resolve({ code, signal })));
        const events = () => fs.existsSync(trace)
            ? fs.readFileSync(trace, 'utf8').trim().split('\n').filter(Boolean).map(JSON.parse) : [];
        const deadline = Date.now() + 10000;
        while (events().filter(event => event.type === 'ready').length < 2 && Date.now() < deadline) {
            await new Promise(resolve => setTimeout(resolve, 10));
        }
        assert.equal(events().filter(event => event.type === 'ready').length, 2, output);
        child.kill(signal);
        assert.deepEqual(await completion, { code: status, signal: null }, output);
        assert.deepEqual(events().filter(event => event.type === 'signal').map(event => event.process).sort(),
            ['browser', 'playwright']);
        assert.ok(events().every(event => event.type !== 'merge'));
    });
}
